namespace sv_07acd2f74f0443e687e46dd5e374a2a5.Services;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_07acd2f74f0443e687e46dd5e374a2a5.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector"></div>
        }
    }
</div>

@* Validation errors *@
@if (Errors.Count > 0)
{
    <div class="validation-errors">
        <ul>
            @foreach (var error in Errors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

@* Step Content *@
<div class="step-content">
    @switch (CurrentStep)
    {
        case 0:
            @* Step 1 — Personal Info *@
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" @bind="FullName" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="Email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="Phone" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" @bind="Address" />
            </div>
            <div class="form-actions">
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
            break;

        case 1:
            @* Step 2 — Work History *@
            <h2>Work History</h2>
            @for (int i = 0; i < WorkEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <h3>Position @(index + 1)</h3>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="WorkEntries[index].Company" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="WorkEntries[index].Title" />
                    </div>
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" @bind="WorkEntries[index].StartDate" />
                    </div>
                    <div class="form-group">
                        <label>
                            <input type="checkbox" @bind="WorkEntries[index].IsCurrent" /> Currently working here
                        </label>
                    </div>
                    @if (!WorkEntries[index].IsCurrent)
                    {
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="WorkEntries[index].EndDate" />
                        </div>
                    }
                    <div class="form-group">
                        <label>Description</label>
                        <textarea @bind="WorkEntries[index].Description"></textarea>
                    </div>
                </div>
            }
            <button class="btn-add" @onclick="AddWorkEntry">Add Another Position</button>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
            break;

        case 2:
            @* Step 3 — References *@
            <h2>References</h2>
            @for (int i = 0; i < References.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <h3>Reference @(index + 1)</h3>
                    @if (References.Count > 2)
                    {
                        <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="References[index].Name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" @bind="References[index].Relationship" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="References[index].Email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="References[index].Phone" />
                    </div>
                </div>
            }
            @if (References.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">Add Reference</button>
            }
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
            break;

        case 3:
            @* Step 4 — Cover Letter *@
            <h2>Cover Letter</h2>
            <div class="form-group">
                <textarea class="cover-letter" @bind="CoverLetter" @bind:event="oninput" maxlength="2000"></textarea>
                <div class="char-count">@CoverLetter.Length / 2000 characters</div>
            </div>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
            break;

        case 4:
            @* Step 5 — Review & Submit *@
            <h2>Review & Submit</h2>

            @if (IsSubmitted)
            {
                <div class="confirmation">
                    <h3>&#10003; Application Submitted Successfully!</h3>
                    <p>Your application ID is: <strong>@ApplicationId</strong></p>
                </div>
            }
            else
            {
                <div class="review-section">
                    <h3>Personal Information <a class="edit-link" @onclick="() => GoToStep(0)">Edit</a></h3>
                    <dl>
                        <dt>Full Name</dt><dd>@FullName</dd>
                        <dt>Email</dt><dd>@Email</dd>
                        <dt>Phone</dt><dd>@Phone</dd>
                        <dt>Address</dt><dd>@Address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <h3>Work History <a class="edit-link" @onclick="() => GoToStep(1)">Edit</a></h3>
                    @foreach (var entry in WorkEntries)
                    {
                        <div class="review-entry">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            @entry.StartDate.ToString("MMM yyyy") &ndash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p>@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <h3>References <a class="edit-link" @onclick="() => GoToStep(2)">Edit</a></h3>
                    @foreach (var reference in References)
                    {
                        <div class="review-entry">
                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
                            @reference.Email | @reference.Phone
                        </div>
                    }
                </div>

                <div class="review-section">
                    <h3>Cover Letter <a class="edit-link" @onclick="() => GoToStep(3)">Edit</a></h3>
                    <p class="cover-letter-preview">@CoverLetter</p>
                </div>

                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsSubmitting">
                        @(IsSubmitting ? "Submitting..." : "Submit Application")
                    </button>
                </div>
            }
            break;
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private List<string> Errors { get; set; } = new();

    // Step 1 fields
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    // Step 2 fields
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string CoverLetter { get; set; } = string.Empty;

    // Step 5 state
    private bool IsSubmitting { get; set; }
    private bool IsSubmitted { get; set; }
    private int ApplicationId { get; set; }

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < CurrentStep)
        {
            CurrentStep = stepIndex;
            Errors.Clear();
        }
    }

    private void GoToStep(int stepIndex)
    {
        CurrentStep = stepIndex;
        Errors.Clear();
    }

    private async Task NextStep()
    {
        Errors.Clear();

        if (!await ValidateCurrentStep())
            return;

        CurrentStep++;
    }

    private void PreviousStep()
    {
        Errors.Clear();
        if (CurrentStep > 0)
            CurrentStep--;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName)) Errors.Add("Full Name is required.");
                if (string.IsNullOrWhiteSpace(Email)) Errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(Phone)) Errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(Address)) Errors.Add("Address is required.");
                if (Errors.Count == 0 && !string.IsNullOrWhiteSpace(Email))
                {
                    var emailValid = await ApplicationService.ValidateEmailAsync(Email);
                    if (!emailValid) Errors.Add("The email address is not valid.");
                }
                break;

            case 1:
                for (int i = 0; i < WorkEntries.Count; i++)
                {
                    var entry = WorkEntries[i];
                    if (string.IsNullOrWhiteSpace(entry.Company)) Errors.Add($"Position {i + 1}: Company Name is required.");
                    if (string.IsNullOrWhiteSpace(entry.Title)) Errors.Add($"Position {i + 1}: Job Title is required.");
                    if (entry.StartDate == default) Errors.Add($"Position {i + 1}: Start Date is required.");
                }
                break;

            case 2:
                for (int i = 0; i < References.Count; i++)
                {
                    var r = References[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) Errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) Errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) Errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) Errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;

            case 3:
                // Cover letter is optional, no validation needed
                break;
        }

        return Errors.Count == 0;
    }

    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        IsSubmitting = true;

        var application = new JobApplication(
            new PersonalInfo(FullName, Email, Phone, Address),
            new WorkHistory(WorkEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            CoverLetter
        );

        ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        IsSubmitted = true;
        IsSubmitting = false;
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 1;
    cursor: pointer;
}

.step.future {
    opacity: 0.4;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #ccc;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    color: #fff;
    font-size: 0.9rem;
}

.step.active .step-circle {
    background: #0d6efd;
}

.step.completed .step-circle {
    background: #198754;
}

.step-label {
    margin-top: 0.25rem;
    font-size: 0.75rem;
    text-align: center;
    max-width: 80px;
}

.step-connector {
    width: 40px;
    height: 2px;
    background: #ccc;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1.25rem;
}

.step-content {
    max-width: 700px;
    margin: 0 auto;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.form-group textarea.cover-letter {
    min-height: 200px;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 1rem;
}

.btn-next, .btn-back, .btn-submit, .btn-add, .btn-remove {
    padding: 0.5rem 1.5rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

.btn-next {
    background: #0d6efd;
    color: #fff;
    margin-left: auto;
}

.btn-back {
    background: #6c757d;
    color: #fff;
}

.btn-submit {
    background: #198754;
    color: #fff;
    margin-left: auto;
}

.btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-add {
    background: #0d6efd;
    color: #fff;
    margin-top: 0.5rem;
}

.btn-remove {
    background: #dc3545;
    color: #fff;
    float: right;
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.work-entry-card, .reference-card {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1rem;
    overflow: hidden;
}

.validation-errors {
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    border-radius: 4px;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    max-width: 700px;
    margin-left: auto;
    margin-right: auto;
}

.validation-errors ul {
    margin: 0;
    padding-left: 1.25rem;
    color: #842029;
}

.review-section {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-section h3 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 0;
}

.edit-link {
    font-size: 0.85rem;
    color: #0d6efd;
    cursor: pointer;
    text-decoration: underline;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.review-entry:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
}

.confirmation {
    text-align: center;
    padding: 2rem;
    background: #d1e7dd;
    border: 1px solid #badbcc;
    border-radius: 8px;
}

.confirmation h3 {
    color: #0f5132;
}

