+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    padding: 1rem;
+    margin-bottom: 1rem;
+    overflow: hidden;
+}
+
+.validation-errors {
+    background: #f8d7da;
+    border: 1px solid #f5c2c7;
+    border-radius: 4px;
+    padding: 0.75rem 1rem;
+    margin-bottom: 1rem;
+    max-width: 700px;
+    margin-left: auto;
+    margin-right: auto;
+}
+
+.validation-errors ul {
+    margin: 0;
+    padding-left: 1.25rem;
+    color: #842029;
+}
+
+.review-section {
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    padding: 1rem;
+    margin-bottom: 1rem;
+}
+
+.review-section h3 {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-top: 0;
+}
+
+.edit-link {
+    font-size: 0.85rem;
+    color: #0d6efd;
+    cursor: pointer;
+    text-decoration: underline;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 600;
+}
+
+.review-entry {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-entry:last-child {
+    border-bottom: none;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+}
+
+.confirmation {
+    text-align: center;
+    padding: 2rem;
+    background: #d1e7dd;
+    border: 1px solid #badbcc;
+    border-radius: 8px;
+}
+
+.confirmation h3 {
+    color: #0f5132;
+}
